def total(base: Int) -> Int = {
  def add(delta: Int) -> Int = { return base + delta }
  return add(1)
}

def value() -> Int = {
  let base = 40
  return { => base + 2 }()
}

def current() -> Int = {
  var value = 1
  def read() -> Int = { return value }
  value = 2
  return read()
}

def useNow(f: #scoped () -> Int) -> Int = { return f() }
def demo(base: Int) -> Int = {
  return useNow({ => base + 1 })
}

def answer() -> Int = {
  let base = 40
  let f = #pure { => base + 2 }
  return f()
}

def report(prefix: String) effects {io} = {
  def emitLine(value: String) effects {io} = { print(prefix + value) }
  emitLine("ready")
}

def makeAdder(seed: Int) -> (Int) -> Int = {
  return [copy seed] { delta: Int =>
    def add(extra: Int) -> Int = { return seed + delta + extra }
    return add(1)
  }
}

def snapshot() -> Int = {
  var value = 1
  let read = [copy value] { => value }
  value = 2
  return read()
}

def demo() -> Int = {
  let f = [] { => ModuleDefaults.answer() }
  return f()
}

def demo(base: Int) -> Int = {
  let f = [base] { => base + 1 }
  return f()
}

