def bad(base: Int) -> () -> Int = {
  def read() -> Int = { return base }
  return read
}

def bad(box: Box<() -> Int>, base: Int) = {
  box.callback = { => base }
}

def bad() -> Int = {
  var total = 0
  def bump() = { total = total + 1 }
  bump()
  return total
}

def bad(resource: File) = {
  def take() = { consume(resource) }
  take()
}

def bad(base: Int) = {
  def#async read() -> Int = { return base }
  await read()
}

def bad(base: Int) = {
  let values = generator { yield base }
  consume(values)
}

def bad(actor: Worker, base: Int) = {
  actor:~submit({ => base })
}

def bad(base: Int) -> Int = {
  let f = [] { => base + 1 }
  return f()
}

def bad(value: Payload) = {
  def read() = { inspect(value) }
  consume(value)
  read()
}

def bad() -> Int = {
  var shared = 1
  let f = #pure { => shared }
  return f()
}

def bad(limit: Int) = {
  def#guard check(value: Int) -> Bool = { return value < limit }
  require check(1)
}

def bad(values: [Int]) -> &Int = {
  def first() -> &Int = { return &values[0] }
  return first()
}

def bad(seed: Int, offset: Int) -> () -> Int = {
  let f = [copy seed] { => seed + offset }
  return f
}
